import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.FeatureRegistry{Features:
# []protocol.GenerationFeature{{Name: "minecraft:oak", JSON: []byte("{}")}}}
ONE_FEATURE = bytes.fromhex("010d6d696e6563726166743a6f616b027b7d")

# generated by gophertunnel b8bd735:
# packet.FeatureRegistry{}
NO_FEATURES = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.FeatureRegistryPacket(
            features_data_list=[
                v2225.FeatureRegistry.FeatureBinaryJsonFormat(feature_name="minecraft:oak", binary_json_output="{}")
            ]
        ),
        ONE_FEATURE,
        id="one-feature",
    ),
    pytest.param(v2225.FeatureRegistryPacket(), NO_FEATURES, id="no-features"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_feature_registry_is_packet_191(version):
    assert version.PACKETS[191] is version.FeatureRegistryPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_feature_registry_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_feature_registry_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
